#pragma once

#ifndef RELU_KERNEL_H
#define RELU_KERNEL_H

#include <algorithm>

#include "kernel_operator.h"
#include "kernel_common.h"
#include "relu_tiling.h"

template <typename dataType>
class ReluKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), tiling_.M * tiling_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), tiling_.M * tiling_.N);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(xInQueue_, 1, tiling_.N * sizeof(dataType));
            pipe_->InitBuffer(yOutQueue_, 1, tiling_.N * sizeof(dataType));
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe_->InitBuffer(xCastBuf_, tiling_.N * sizeof(float));
                pipe_->InitBuffer(yCastBuf_, tiling_.N * sizeof(float));
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tiling_.tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tiling_.tasksPerCore + localIdx;
                if (bx >= BlockCount()) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * tiling_.blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < tiling_.M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline int32_t BlockCount() const
    {
        return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM;
    }

    __aicore__ inline void CopyInX(int32_t rowIdx)
    {
        xInQueue_.AllocTensor<dataType>(xInLocal_);
        AscendC::DataCopy(xInLocal_, xGM_[rowIdx * tiling_.N], static_cast<uint32_t>(tiling_.N));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        yOutQueue_.DeQue<dataType>(yOutLocal_);
        AscendC::DataCopy(yGM_[rowIdx * tiling_.N], yOutLocal_, static_cast<uint32_t>(tiling_.N));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void ComputeRow(int32_t rowIdx)
    {
        xInQueue_.DeQue<dataType>(xInLocal_);
        yOutQueue_.AllocTensor<dataType>(yOutLocal_);

        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::LocalTensor<float> xLocal = xInLocal_.template ReinterpretCast<float>();
            AscendC::LocalTensor<float> yLocal = yOutLocal_.template ReinterpretCast<float>();
            AscendC::Relu(yLocal, xLocal, tiling_.N);
        } else {
            AscendC::LocalTensor<float> xCast = xCastBuf_.Get<float>();
            AscendC::LocalTensor<float> yCast = yCastBuf_.Get<float>();

            AscendC::Cast(xCast, xInLocal_, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::Relu(yCast, xCast, tiling_.N);

            AscendC::Cast(yOutLocal_, yCast, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
        }

        yOutQueue_.EnQue(yOutLocal_);
        xInQueue_.FreeTensor(xInLocal_);
    }

    __aicore__ inline void ProcessRow(int rowIdx)
    {
        CopyInX(rowIdx);
        ComputeRow(rowIdx);
        CopyOutY(rowIdx);
    }

private:
    ReluKernelTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};
    int subBlockRows_{0};

    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, 0> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
};

#endif

relu_fp16.cpp.content:
#include "relu_kernel.h"

extern "C" __global__ __aicore__ void relu_custom_fp16(
    GM_ADDR x, GM_ADDR y, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    AscendC::TPipe pipe;
    ReluKernel<half> kernel;
    kernel.Init(x, y, tiling, &pipe);
    kernel.Process();
}

extern "C" void relu_do_fp16(
    uint32_t blockDim,
    void *stream,
    uint8_t *x,
    uint8_t *y,
    uint8_t *tiling)
{
    relu_custom_fp16<<<blockDim, nullptr, stream>>>(x, y, tiling);
}

pybind11.cpp.content:
#include <algorithm>

#include <pybind11/pybind11.h>
#include <torch/extension.h>

#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"

#include "relu_tiling.h"

extern "C" void relu_do_fp32(
    uint32_t blockDim,
    void *stream,
    uint8_t *x,
    uint8_t *y,
    uint8_t *tiling);

extern "C" void relu_do_fp16(
    uint32_t blockDim,
    void *stream,
    uint8_t *x,
    uint8_t *y,
    uint8_t *tiling);

extern "C" void relu_do_bf16(
    uint32_t blockDim,
    void *stream,
    uint8_t *x,
    uint8_t *y,
    uint8_t *tiling);

namespace relu_ext {

using LaunchFn = void (*)(uint32_t, void *, uint8_t *, uint8_t *, uint8_t *);

pybind11::tuple run_relu(const at::Tensor &x)
{
    TORCH_CHECK(x.dim() == 2, "x must be [M, N]");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf || x.scalar_type() == at::kBFloat16,
        "x must be float32, float16, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    const auto m = static_cast<int32_t>(x.sizes()[0]);
    const auto n = static_cast<int32_t>(x.sizes()[1]);

    const int32_t mNum = (m + DEFAULT_RELU_BLOCK_M - 1) / DEFAULT_RELU_BLOCK_M;
    const int32_t usedCoreNum = std::min<int32_t>(DEFAULT_RELU_NUM_PHYSICAL_CORES, mNum);
    const int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    at::Tensor y = at::empty_like(x);

    at::Tensor tilingCpu = at::empty(
        {static_cast<long>(sizeof(ReluKernelTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *tiling = reinterpret_cast<ReluKernelTiling *>(tilingCpu.data_ptr());
    tiling->M = m;
    tiling->N = n;
    tiling->blockM = DEFAULT_RELU_BLOCK_M;
    tiling->usedCoreNum = usedCoreNum;
    tiling->tasksPerCore = tasksPerCore;
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);
    LaunchFn launch = nullptr;
    if (x.scalar_type() == at::kFloat) {
        launch = relu_do_fp32;
    } else if (x.scalar_type() == at::kHalf) {
        launch = relu_do_fp16;
    } else if (x.scalar_type() == at::kBFloat16) {
        launch = relu_do_bf16;
    } else {
        TORCH_CHECK(false, "unsupported dtype");
    }
    launch(
        usedCoreNum,
        aclStream,
        static_cast<uint8_t *>(const_cast<void *>(x.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(y.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(tilingNpu.storage().data())));
    return pybind11::make_tuple(y);
}

}  // namespace relu_ext

PYBIND11_MODULE(_relu_ext, m)
{
    m.doc() = "relu extension";
    m.def("run_relu", &relu_ext::run_relu, "");
}

