#pragma once

#ifndef RELU_TILING_H
#define RELU_TILING_H

#include <cstdint>

constexpr int32_t DEFAULT_RELU_BLOCK_M = 128;
constexpr int32_t DEFAULT_RELU_NUM_PHYSICAL_CORES = 32;

struct ReluKernelTiling {
    int32_t M;
    int32_t N;
    int32_t blockM;
    int32_t usedCoreNum;
    int32_t tasksPerCore;
};

#endif
